(() => {
 const $=(q,root=document)=>root.querySelector(q);
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const ico=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
 const now=Date.now();
 const ago=hours=>new Date(now-hours*3600000).toISOString();
 const topics=['资料完整性','用药信息核对','循证资料讨论'];
 const seeds=[
  {id:'seed-1',title:'日达仙用药随访：如何补全病历资料',topic:'资料完整性',author:{name:'陈医生',department:'内科'},createdAt:ago(3),body:'【匿名病例 A】\n患者身份信息已隐藏。本次随访围绕日达仙相关药品资料的核对与病历信息完整性展开讨论。\n\n【病史资料】\n与本次讨论相关的既往病史、既往用药情况及随访记录仍需进一步整理。\n\n【用药信息】\n药品名称：日达仙。具体剂型、实际使用记录及完整合并用药清单待核对。\n\n【讨论问题】\n在查阅说明书和相关资料前，还需要补充哪些病历信息？如何按病史、检查资料和用药记录进行梳理？',images:[{src:'assets/case-sample.svg',redacted:true}],privacyConfirmed:true,comments:[]},
  {id:'seed-2',title:'合并用药背景下的日达仙资料核对',topic:'用药信息核对',author:{name:'王医生',department:'全科医学科'},createdAt:ago(12),body:'【匿名病例 B】\n患者希望在随访时完善用药资料。本病例仅保留与资料讨论有关的内容，已移除身份信息。\n\n【现有记录】\n记录中提及日达仙及其他合并用药，但部分药品的具体名称、剂型、使用时间仍待确认。\n\n【待补充资料】\n检查结果日期、既往不良反应记录及完整的处方药、非处方药和补充剂清单。\n\n【讨论问题】\n如何建立一份便于复核的合并用药清单？说明书版本与资料来源应如何记录？',images:[],privacyConfirmed:true,comments:[{id:'seed-comment-1',author:'李医生',category:'用药资料',text:'建议先补全药品名称、剂型与实际使用记录，再逐项记录资料来源和说明书版本，便于后续复核。',createdAt:ago(8)},{id:'seed-comment-2',author:'赵医生',category:'信息完整性',text:'可以增加检查日期和既往相关记录的时间顺序，病例讨论时更容易看清哪些资料仍需补充。',createdAt:ago(5)}]},
  {id:'seed-3',title:'日达仙相关病例的循证资料讨论',topic:'循证资料讨论',author:{name:'周医生',department:'内科'},createdAt:ago(28),body:'【匿名病例 C】\n本病例希望围绕日达仙相关的学术资料建立阅读框架，不包含患者身份信息。\n\n【已有资料】\n已整理药品名称与部分随访记录，拟进一步查阅获批说明书、相关指南和原始研究。\n\n【讨论问题】\n如何将病例中的实际问题转化为可检索的问题？阅读研究时，哪些人群特征、研究终点和适用边界需要记录？',images:[],privacyConfirmed:true,comments:[{id:'seed-comment-3',author:'孙医生',category:'循证讨论',text:'建议先明确本次讨论的问题，再记录资料出处、发表时间与版本。研究结论与适用人群可以分别整理。',createdAt:ago(20)}]},
  {id:'seed-4',title:'日达仙用药记录与随访信息整理',topic:'资料完整性',author:{name:'刘医生',department:'全科医学科'},createdAt:ago(52),body:'【匿名病例 D】\n患者身份字段已移除，拟整理日达仙相关用药记录及随访信息。\n\n【现有资料】\n已记录药品名称，具体使用情况、合并用药与检查资料尚未形成完整清单。\n\n【讨论问题】\n如何用统一的资料模板整理本次记录？病史、检查和用药信息中，应优先核对哪些缺项？',images:[],privacyConfirmed:true,comments:[]}
 ];
 let database=null,posts=[],loadError=null;
 const openDatabase=()=>new Promise((resolve,reject)=>{const request=indexedDB.open('knowdrug-doctor-caseboard',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('posts'))request.result.createObjectStore('posts',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('blocked'));});
 const readAll=()=>new Promise((resolve,reject)=>{const tx=database.transaction('posts','readonly');const request=tx.objectStore('posts').getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
 const persist=post=>new Promise((resolve,reject)=>{if(!database){reject(new Error('storage unavailable'));return;}const tx=database.transaction('posts','readwrite');tx.objectStore('posts').put(post);tx.oncomplete=()=>{const index=posts.findIndex(p=>p.id===post.id);if(index<0)posts.unshift(post);else posts[index]=post;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});
 async function init(){database=await openDatabase();posts=await readAll();if(!posts.length){for(const record of seeds)await persist(record);}posts.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
 const ready=init().catch(error=>{loadError=error;});
 let listFilter='all',query='',renderSequence=0;
 const emptyDraft=()=>({title:'',body:'',topic:topics[0],photos:[],textChecked:false,imagesChecked:false,loading:false});
 let draft=emptyDraft();
 let editor=null;
 let commentCategory='信息完整性';
 const formatDate=value=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
 const clone=value=>JSON.parse(JSON.stringify(value));
 const safeImage=src=>/^data:image\/(?:jpeg|png|webp);base64,/.test(src)||src==='assets/case-sample.svg'?src:'';
 const privacyBanner=(heading='发布前，请隐藏患者信息')=>`<div class="privacy-banner" role="note">${ico('shield')}<div><strong>${heading}</strong><p>请移除或遮挡患者姓名、联系方式、证件号、病案号、住院号、床号、条形码、二维码及可识别的面部照片。</p><p class="privacy-note">请人工核对文字与每张图片，系统不会自动完成脱敏。</p></div></div>`;
 function identityIssue(text){
  if(/1[3-9]\d{9}/.test(text))return '内容可能包含手机号，请隐藏后再发布。';
  if(/\d{17}[\dXx]/.test(text))return '内容可能包含证件号，请隐藏后再发布。';
  const fields=[...text.matchAll(/(?:患者姓名|姓名|联系电话|身份证号|住院号|病案号|床号)\s*[:：]\s*([^\n，,；;]+)/g)];
  if(fields.some(match=>!/(已隐藏|已脱敏|匿名|未提供|已移除|\*|×|—|█)/.test(match[1])))return '请先隐藏姓名、联系方式或病案号等身份字段。';
  return '';
 }
 function card(post){const count=post.comments.length;return `<button class="case-card" data-case-action="detail" data-id="${esc(post.id)}"><div class="case-card-top"><span class="resource-badge">日达仙</span><span class="resource-badge">${esc(post.topic)}</span><span class="case-status">${count?'可参与点评':'待点评'}</span></div><h3>${esc(post.title)}</h3><p class="case-card-summary">${esc(post.body.replace(/【[^】]*】/g,'').replace(/\s+/g,' ').trim().slice(0,95))}</p><div class="case-card-footer"><span class="case-person">${esc(post.author.name[0])}</span><span>${esc(post.author.name)}</span><time>${formatDate(post.createdAt)}</time><span class="case-comment-count">${ico('chat')}${count}条点评</span></div></button>`;}
 function listHtml(){const found=posts.filter(p=>(listFilter!=='pending'||!p.comments.length)&&(listFilter!=='mine'||p.author.isMine)&&`${p.title}${p.topic}${p.body}`.includes(query)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return found.length?found.map(card).join(''):`<div class="empty-state">${ico('case')}<h3>${listFilter==='mine'?'暂无发布的病历':'暂无匹配的病历'}</h3></div>`;}
 function renderList(){return `<div class="case-toolbar"><h2>病历列表</h2><button class="primary-button" data-case-action="publish">+ 发布病历</button></div><label class="case-search">${ico('search')}<input id="case-search" type="search" value="${esc(query)}" placeholder="搜索病历主题" aria-label="搜索病历"></label><div class="case-filters" role="group" aria-label="病历筛选">${[['all','全部'],['pending','待点评'],['mine','我的发布']].map(([id,label])=>`<button class="case-filter ${listFilter===id?'active':''}" data-case-action="filter" data-filter="${id}" aria-pressed="${listFilter===id}">${label}</button>`).join('')}</div><div class="case-list" id="case-list">${listHtml()}</div>`;}
 function renderDetail(context){const post=posts.find(p=>p.id===context.caseId);if(!post)return '<div class="empty-state"><h3>未找到这份病历</h3></div>';const comments=[...post.comments].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const sections=post.body.split(/(?=【)/).filter(t=>t.trim());return `<div class="case-card-top"><span class="resource-badge">日达仙</span><span class="resource-badge">${esc(post.topic)}</span></div><h2 class="case-page-title">${esc(post.title)}</h2><div class="case-author-line"><span class="case-person">${esc(post.author.name[0])}</span><div>${esc(post.author.name)} · ${esc(post.author.department)}<time>${formatDate(post.createdAt)}</time></div></div><section class="case-detail-panel">${sections.map(text=>{const match=text.match(/^【([^】]+)】\s*([\s\S]*)/);return `<div class="case-detail-section"><h3>${esc(match?match[1]:'病例描述')}</h3><p>${esc(match?match[2].trim():text)}</p></div>`;}).join('')}${post.images.length?`<div class="case-detail-section"><h3>病历图片</h3><div class="case-attachments">${post.images.map((image,index)=>`<button class="case-attachment" data-case-action="image" data-id="${esc(post.id)}" data-index="${index}" aria-label="查看病历图片${index+1}"><img src="${esc(safeImage(image.src))}" alt="病历图片${index+1}"></button>`).join('')}</div></div>`:''}</section><div class="case-section-head" id="case-comments"><h2>医生点评<span class="count">${comments.length}</span></h2><button class="text-button" data-case-action="write">写点评</button></div><div class="case-comments">${comments.length?comments.map(comment=>`<article class="case-comment"><div class="case-comment-head"><span class="case-person">${esc(comment.author[0])}</span><span>${esc(comment.author)}</span><time>${formatDate(comment.createdAt)}</time></div><p>${esc(comment.text)}</p><span class="tag">${esc(comment.category)}</span></article>`).join(''):'<div class="case-no-comments">暂无点评，欢迎分享您的看法</div>'}</div><section class="case-comment-form" id="case-comment-form"><h3>发表点评</h3><label class="sr-only" for="case-comment-text">点评内容</label><textarea id="case-comment-text" maxlength="1000" placeholder="从病历完整性、用药资料或循证依据等角度分享看法，请勿填写患者身份信息。"></textarea><div class="case-comment-options" role="group" aria-label="点评方向">${['信息完整性','用药资料','循证讨论'].map(category=>`<button class="${commentCategory===category?'active':''}" data-case-action="comment-category" data-category="${category}">${category}</button>`).join('')}</div><button class="primary-button" data-case-action="submit-comment" data-id="${esc(post.id)}">发布点评</button></section>`;}
 function photoGrid(){return draft.photos.map((image,index)=>`<div class="upload-photo"><button data-case-action="redact" data-index="${index}" aria-label="遮挡第${index+1}张图片中的患者信息"><img src="${esc(image.sanitized)}" alt="待发布病历图片${index+1}"></button><span class="photo-label">图片 ${index+1}${image.rects.length?' · 已添加遮挡':''}</span><div class="photo-actions"><button data-case-action="redact" data-index="${index}" ${draft.loading?'disabled':''}>遮挡信息</button><button data-case-action="remove-image" data-index="${index}" ${draft.loading?'disabled':''}>移除</button></div></div>`).join('')+(draft.photos.length<6?`<button class="upload-add" data-case-action="choose-images" ${draft.loading?'disabled':''}>${ico('upload')}<span>${draft.loading?'图片处理中…':'添加病历图片'}</span></button>`:'');}
 function renderPublish(){return `${privacyBanner()}<section class="case-publish-card"><label class="case-field-label" for="case-title">病历标题</label><input id="case-title" class="case-text-input" value="${esc(draft.title)}" maxlength="60" placeholder="请填写病例讨论主题，不要包含患者姓名"><label class="case-field-label" for="case-topic">讨论方向</label><select id="case-topic" class="case-select">${topics.map(topic=>`<option ${draft.topic===topic?'selected':''}>${topic}</option>`).join('')}</select><label class="case-field-label" for="case-body">病例描述</label><textarea id="case-body" class="case-publish-text" maxlength="6000" placeholder="填写已脱敏的病史、相关检查、日达仙用药记录与讨论问题。">${esc(draft.body)}</textarea><div class="case-form-count" id="case-body-count">${draft.body.length} / 6000</div></section><section class="case-publish-card"><label class="case-field-label">病历图片<span class="optional">选填 · 最多6张</span></label><div class="case-image-warning"><strong>图片也需要脱敏</strong><br>请检查截图边缘、页眉、报告单、二维码及面部照片。可点击图片使用黑块遮挡。</div><div class="upload-grid">${photoGrid()}</div><input id="case-file-input" type="file" class="sr-only" accept="image/jpeg,image/png,image/webp" multiple aria-label="选择病历图片">${draft.loading?'<div class="upload-busy" role="status">图片处理中，请稍候…</div>':''}</section><section class="privacy-checklist"><h3>发布前，请再次确认</h3><label class="privacy-checkbox"><input id="case-text-confirm" type="checkbox" ${draft.textChecked?'checked':''}><span>我已隐藏标题和病例文字中的患者身份信息</span></label>${draft.photos.length?`<label class="privacy-checkbox"><input id="case-images-confirm" type="checkbox" ${draft.imagesChecked?'checked':''}><span>我已逐张检查图片，遮挡所有可识别患者身份的信息</span></label>`:''}</section><button class="primary-button publish-case-button" data-case-action="review-publish" ${draft.loading?'disabled':''}>确认脱敏并发布</button>`;}
 function renderRedactor(context){const photo=draft.photos[Number(context.imageIndex)];if(!photo)return '<div class="empty-state"><h3>未找到这张图片</h3></div>';editor={index:Number(context.imageIndex),rects:clone(photo.rects),image:null,drag:null,pointer:null};return `<div class="redact-guide">${ico('shield')}<div><strong>拖动框选患者身份信息</strong><br>姓名、号码、二维码及面部等区域请用黑块完全遮住。保存后，遮挡会合入图片。</div></div><div class="redact-canvas-wrap"><canvas id="redact-canvas" aria-label="拖动框选需要隐藏的患者信息"></canvas></div><div class="upload-busy" id="redact-status" role="status">正在准备图片…</div><div class="redact-toolbar"><button data-case-action="undo-mask" id="redact-undo">撤销</button><button data-case-action="clear-masks">清空遮挡</button><button class="primary-button" data-case-action="save-mask">保存遮挡</button></div>`;}
 function drawMask(){const canvas=$('#redact-canvas');if(!canvas||!editor?.image)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(editor.image,0,0);ctx.fillStyle='#182231';[...editor.rects,...(editor.drag?[editor.drag]:[])].forEach(r=>ctx.fillRect(r.x,r.y,r.w,r.h));$('#redact-status').textContent=editor.rects.length?`已遮挡 ${editor.rects.length} 处，请确认边缘已完整覆盖`:'拖动框选需要隐藏的信息';$('#redact-undo').disabled=!editor.rects.length;}
 function setupEditor(){const canvas=$('#redact-canvas');if(!canvas||!editor)return;const photo=draft.photos[editor.index];const image=new Image();image.onload=()=>{if($('#redact-canvas')!==canvas||!editor)return;editor.image=image;canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;drawMask();};image.src=photo.base;
  const point=event=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width,(event.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(event.clientY-r.top)*canvas.height/r.height))};};
  let origin=null;
  canvas.addEventListener('pointerdown',event=>{if(!editor?.image||editor.pointer!==null||(event.pointerType==='mouse'&&event.button!==0))return;event.preventDefault();editor.pointer=event.pointerId;origin=point(event);canvas.setPointerCapture?.(event.pointerId);});
  canvas.addEventListener('pointermove',event=>{if(!origin||editor?.pointer!==event.pointerId)return;event.preventDefault();const p=point(event);editor.drag={x:Math.min(origin.x,p.x),y:Math.min(origin.y,p.y),w:Math.abs(p.x-origin.x),h:Math.abs(p.y-origin.y)};drawMask();});
  canvas.addEventListener('pointerup',event=>{if(!origin||editor?.pointer!==event.pointerId)return;if(editor.drag&&editor.drag.w>=6&&editor.drag.h>=6)editor.rects.push({...editor.drag});editor.drag=null;editor.pointer=null;origin=null;drawMask();});
  canvas.addEventListener('pointercancel',()=>{if(editor){editor.drag=null;editor.pointer=null;}origin=null;drawMask();});
 }
 async function render(page,context={}){const sequence=++renderSequence;const root=$('#module-page');root.innerHTML='<div class="case-loading" role="status">正在加载病历…</div>';await ready;if(sequence!==renderSequence||currentPage!==page)return;if(loadError){root.innerHTML='<div class="empty-state"><h3>病历暂时无法加载</h3><p>请刷新页面后重试</p></div>';return;}
  if(page==='case')root.innerHTML=renderList();
  if(page==='caseDetail'){root.innerHTML=renderDetail(context);if(context.focusComments)$('#case-comments')?.scrollIntoView({behavior:reduceMotion?'instant':'smooth',block:'start'});}
  if(page==='casePublish')root.innerHTML=renderPublish();
  if(page==='caseRedact'){root.innerHTML=renderRedactor(context);setupEditor();}
 }
 function requestImages(){showModal('上传前，请先隐藏患者信息',`<div class="privacy-intro-sheet">${privacyBanner('图片如含患者信息，请先遮挡')}<p>选择图片后，可以使用“遮挡信息”工具添加黑块；请在最终发布前逐张检查。</p><button class="primary-button" data-case-action="confirm-upload">我已了解，选择图片</button></div>`);}
 const decodePhoto=file=>new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{try{const ratio=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*ratio);canvas.height=Math.round(image.naturalHeight*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.86);resolve({base:src,sanitized:src,rects:[],width:canvas.width,height:canvas.height});}catch(error){reject(error);}finally{URL.revokeObjectURL(url);}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('image decode'));};image.src=url;});
 async function addImages(files){const available=6-draft.photos.length;if(!available){toast('最多上传6张病历图片');return;}const selected=[...files].slice(0,available);if(files.length>available)toast('最多上传6张，已选择剩余可添加数量');draft.loading=true;draft.imagesChecked=false;if(currentPage==='casePublish')$('#module-page').innerHTML=renderPublish();for(const file of selected){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择JPG、PNG或WebP图片');continue;}if(file.size>10*1024*1024){toast('请使用10MB以内的图片');continue;}try{draft.photos.push(await decodePhoto(file));}catch{toast('有一张图片无法读取，请重新选择');}}draft.loading=false;if(currentPage==='casePublish')$('#module-page').innerHTML=renderPublish();}
 function validateDraft(){if(draft.title.trim().length<6){toast('请填写至少6个字的病历标题');$('#case-title')?.focus();return false;}if(draft.body.trim().length<30){toast('请填写至少30字的脱敏病例描述');$('#case-body')?.focus();return false;}const issue=identityIssue(draft.title+'\n'+draft.body);if(issue){toast(issue);return false;}if(!draft.textChecked){toast('请先确认文字中的患者身份信息已隐藏');$('#case-text-confirm')?.focus();return false;}if(draft.photos.length&&!draft.imagesChecked){toast('请逐张检查图片，并确认患者信息已隐藏');$('#case-images-confirm')?.focus();return false;}return true;}
 function reviewPublish(){if(!validateDraft()||draft.loading)return;showModal('确认发布病历',`<h3 class="case-review-title">${esc(draft.title)}</h3><div class="case-review-row"><span>讨论方向</span><b>${esc(draft.topic)}</b></div><div class="case-review-row"><span>病历图片</span><b>${draft.photos.length}张</b></div><div class="case-review-checks"><strong>请再次确认已隐藏患者信息</strong><br>✓ 标题与文字已人工核对${draft.photos.length?`<br>✓ ${draft.photos.length}张图片已逐张检查`:''}<br>姓名、号码、二维码及面部等身份信息不得出现在发布内容中。</div><button class="primary-button full-width-button" data-case-action="confirm-publish">确认并发布</button>`);}
 document.addEventListener('input',event=>{const el=event.target;if(el.id==='case-search'){query=el.value.trim();$('#case-list').innerHTML=listHtml();}if(el.id==='case-title'){draft.title=el.value;draft.textChecked=false;const check=$('#case-text-confirm');if(check)check.checked=false;}if(el.id==='case-body'){draft.body=el.value;draft.textChecked=false;$('#case-body-count').textContent=el.value.length+' / 6000';const check=$('#case-text-confirm');if(check)check.checked=false;}});
 document.addEventListener('change',event=>{const el=event.target;if(el.id==='case-topic')draft.topic=el.value;if(el.id==='case-text-confirm')draft.textChecked=el.checked;if(el.id==='case-images-confirm')draft.imagesChecked=el.checked;if(el.id==='case-file-input'&&el.files?.length)addImages(el.files);});
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-case-action]');if(!button)return;const action=button.dataset.caseAction;const index=Number(button.dataset.index);const id=button.dataset.id;
  if(action==='detail')navigate('caseDetail',{context:{caseId:id}});
  if(action==='publish')navigate('casePublish');
  if(action==='filter'){listFilter=button.dataset.filter;$('#module-page').innerHTML=renderList();}
  if(action==='write'){$('#case-comment-form').scrollIntoView({behavior:reduceMotion?'instant':'smooth',block:'start'});$('#case-comment-text').focus({preventScroll:true});}
  if(action==='comment-category'){commentCategory=button.dataset.category;document.querySelectorAll('[data-case-action="comment-category"]').forEach(b=>b.classList.toggle('active',b===button));}
  if(action==='submit-comment'){
   const text=$('#case-comment-text').value.trim();if(text.length<10){toast('请填写至少10字的点评');return;}const issue=identityIssue(text);if(issue){toast(issue);return;}const post=clone(posts.find(p=>p.id===id));post.comments.unshift({id:'comment-'+Date.now(),author:doctor.name,category:commentCategory,text,createdAt:new Date().toISOString()});button.disabled=true;try{await persist(post);await render('caseDetail',{caseId:id,focusComments:true});toast('点评已发布');}catch{toast('点评保存失败，请稍后重试');button.disabled=false;}
  }
  if(action==='choose-images')requestImages();
  if(action==='confirm-upload'){$('#modal').close();$('#case-file-input')?.click();}
  if(action==='remove-image'){draft.photos.splice(index,1);draft.imagesChecked=false;$('#module-page').innerHTML=renderPublish();}
  if(action==='redact')navigate('caseRedact',{context:{imageIndex:index}});
  if(action==='undo-mask'){editor?.rects.pop();drawMask();}
  if(action==='clear-masks'){if(editor){editor.rects=[];editor.drag=null;drawMask();}}
  if(action==='save-mask'){if(!editor?.image)return;editor.drag=null;drawMask();const photo=draft.photos[editor.index];photo.rects=clone(editor.rects);photo.sanitized=$('#redact-canvas').toDataURL('image/jpeg',.92);draft.imagesChecked=false;history.back();toast('图片已保存，请继续核对其他患者信息');}
  if(action==='image'){const post=posts.find(p=>p.id===id);const image=post?.images[index];if(image)showModal('病历图片 '+(index+1),`<img class="case-full-image" src="${esc(safeImage(image.src))}" alt="病历图片${index+1}">`);}
  if(action==='review-publish')reviewPublish();
  if(action==='confirm-publish'){
   if(draft.loading)return;const post={id:'case-'+Date.now(),title:draft.title.trim(),body:draft.body.trim(),topic:draft.topic,author:{name:doctor.name,department:doctor.department,isMine:true},createdAt:new Date().toISOString(),privacyConfirmed:true,images:draft.photos.map(p=>({src:p.sanitized,redacted:p.rects.length>0,width:p.width,height:p.height})),comments:[]};button.disabled=true;button.textContent='发布中…';try{await persist(post);draft=emptyDraft();editor=null;closeModalThen(()=>{navigate('caseDetail',{context:{caseId:post.id},replace:true});toast('病历已发布');});}catch{toast('病历保存失败，请稍后重试');button.disabled=false;button.textContent='确认并发布';}
  }
 });
 window.CaseBoard={render};
})();
